-- ============================================================
--  Миграция 006: «Сетевой маршрут» — теоретические вопросы
--
--  Числовые задания (IP, маски, шлюзы, маршрутизация) игра генерирует
--  сама — см. includes/network.php. Здесь — только теория: DNS, DHCP,
--  NAT, порты, модель OSI и т.п. Правится в админке: раздел «СЕТЕВОЙ МАРШРУТ».
--
--  level — с какого уровня игры вопрос может выпасть:
--    1 — на всех, 2 — Практик и Эксперт, 3 — только Эксперт.
--
--  Идемпотентна (entrypoint запускает её при каждом старте):
--  таблица создаётся, если её нет; вопросы заливаются только в пустую.
--
--  Откат:  DROP TABLE IF EXISTS network_questions;
-- ============================================================

SET client_encoding = 'UTF8';

BEGIN;

CREATE TABLE IF NOT EXISTS public.network_questions (
    id           serial PRIMARY KEY,
    level        smallint    NOT NULL DEFAULT 1 CHECK (level BETWEEN 1 AND 3),
    question     text        NOT NULL,
    answer1      text        NOT NULL,
    answer2      text        NOT NULL,
    answer3      text        NOT NULL,
    answer4      text        NOT NULL,
    correct      smallint    NOT NULL DEFAULT 0 CHECK (correct BETWEEN 0 AND 3),
    explanation  text        NOT NULL DEFAULT '',
    hidden       boolean     NOT NULL DEFAULT false,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_network_questions_level ON public.network_questions (level);

-- 42 стартовых вопросов — только в пустую таблицу. Верный вариант записан
-- под номером 0; в игре варианты перемешивает сервер.
INSERT INTO public.network_questions (level, question, answer1, answer2, answer3, answer4, correct, explanation)
SELECT v.* FROM (VALUES
    (1, 'Что такое IP-адрес?', 'Адрес устройства в сети', 'Название сайта', 'Пароль от Wi-Fi', 'Модель роутера', 0, 'По IP-адресу пакеты находят нужное устройство, как письмо — дом по почтовому адресу.'),
    (1, 'Из скольких чисел (октетов) состоит адрес IPv4?', '4', '3', '6', '8', 0, 'Например, 192.168.1.10 — четыре числа через точку, каждое занимает 8 бит.'),
    (1, 'В каких пределах лежит каждое число адреса IPv4?', 'От 0 до 255', 'От 0 до 999', 'От 1 до 100', 'От 0 до 1024', 0, 'Каждое число — 8 бит, а в 8 битах помещается 256 значений: от 0 до 255.'),
    (1, 'Какое устройство соединяет домашнюю сеть с интернетом?', 'Роутер', 'Монитор', 'Принтер', 'Сканер', 0, 'Роутер (маршрутизатор) передаёт пакеты между домашней сетью и сетью провайдера.'),
    (1, 'Что делает DHCP-сервер?', 'Раздаёт устройствам IP-адреса', 'Переводит имена сайтов в IP', 'Шифрует трафик', 'Блокирует вирусы', 0, 'Подключился к Wi-Fi — DHCP сам выдал адрес, маску, шлюз и DNS. Имена в IP переводит DNS.'),
    (1, 'Зачем нужен DNS?', 'Переводит имена сайтов в IP-адреса', 'Раздаёт IP-адреса устройствам', 'Ускоряет Wi-Fi', 'Хранит пароли', 0, 'Пакеты ходят по IP-адресам, а люди помнят имена. DNS отвечает, какой IP у gmcode.ru.'),
    (1, 'Что такое шлюз по умолчанию?', 'Роутер для пакетов в другие сети', 'Главный сервер интернета', 'Первый компьютер в сети', 'Пароль администратора', 0, 'Всё, что не в своей подсети, компьютер отправляет на шлюз — обычно это домашний роутер.'),
    (1, 'Что показывает маска подсети?', 'Какая часть IP — номер сети', 'Скрывает IP от хакеров', 'Скорость подключения', 'Имя компьютера в сети', 0, 'Маска 255.255.255.0: первые три числа адреса — номер сети, последнее — номер устройства.'),
    (1, 'Что означает /24 в записи 192.168.1.10/24?', 'Первые 24 бита — номер сети', 'В сети 24 устройства', 'Адрес выдан на 24 часа', 'Скорость 24 Мбит/с', 0, '/24 — это маска 255.255.255.0: 24 единицы подряд, то есть три первых октета.'),
    (1, 'Какая команда проверяет, отвечает ли устройство в сети?', 'ping', 'ls', 'mkdir', 'echo', 0, 'ping 8.8.8.8 отправляет запросы и показывает, за сколько миллисекунд пришёл ответ.'),
    (1, 'Чем Wi-Fi отличается от Ethernet?', 'Wi-Fi — по радио, Ethernet — по кабелю', 'Ничем, это одно и то же', 'Wi-Fi не использует IP-адреса', 'Wi-Fi только для телефонов', 0, 'Оба передают те же IP-пакеты, разница в среде: радиоволны или провод.'),
    (1, 'Что такое сетевой пакет?', 'Порция данных с адресами', 'Установщик программы', 'Тариф провайдера', 'Архив с файлами', 0, 'Данные режутся на пакеты, у каждого есть адрес отправителя и получателя.'),
    (1, 'Какой командой в Windows посмотреть свой IP-адрес?', 'ipconfig', 'ping', 'dir', 'cls', 0, 'ipconfig показывает IP, маску и шлюз каждого сетевого адаптера. В Linux — ip a.'),
    (1, 'Какое устройство соединяет компьютеры внутри одной сети?', 'Коммутатор (свитч)', 'Модем', 'Блок питания', 'Сканер', 0, 'Свитч пересылает данные между устройствами одной сети, роутер — между разными сетями.'),
    (2, 'Какой порт по умолчанию у DNS?', '53', '80', '22', '25', 0, 'DNS слушает порт 53. 80 — HTTP, 22 — SSH, 25 — почта (SMTP).'),
    (2, 'Что делает протокол ARP?', 'Находит MAC-адрес по IP', 'Находит IP по имени сайта', 'Раздаёт IP-адреса', 'Шифрует пакеты', 0, 'Чтобы отправить кадр соседу, нужен его MAC. ARP спрашивает всю локальную сеть: «у кого IP 192.168.1.5?»'),
    (2, 'Что такое широковещательный адрес (broadcast)?', 'Адрес «всем узлам подсети»', 'Адрес роутера', 'Первый адрес сети', 'Адрес DNS-сервера', 0, 'Пакет на broadcast (в сети /24 это x.x.x.255) получат все устройства подсети.'),
    (2, 'Что такое адрес сети?', 'Первый адрес, обозначает всю подсеть', 'Адрес роутера', 'Адрес любого компьютера', 'Последний адрес подсети', 0, 'В 192.168.1.0/24 адрес сети — 192.168.1.0. Устройству его не дают.'),
    (2, 'Зачем домашнему роутеру NAT?', 'Чтобы все выходили через один внешний IP', 'Чтобы ускорить Wi-Fi', 'Чтобы раздавать IP-адреса', 'Чтобы блокировать рекламу', 0, 'Провайдер даёт роутеру один внешний адрес, а NAT подменяет на него частные адреса домашних устройств.'),
    (2, 'Чем коммутатор отличается от роутера?', 'Свитч — одна сеть, роутер — между сетями', 'Свитч беспроводной, роутер — нет', 'Ничем, это одно и то же', 'Роутер работает только с Wi-Fi', 0, 'Свитч соединяет устройства одной сети по MAC-адресам, роутер передаёт пакеты между сетями по IP.'),
    (2, 'По каким адресам обычный (L2) свитч пересылает кадры?', 'По MAC-адресам', 'По IP-адресам', 'По именам сайтов', 'По номерам портов TCP', 0, 'Свитч работает на канальном уровне и запоминает, за каким своим портом какой MAC-адрес.'),
    (2, 'Что такое TTL в IP-пакете?', 'Счётчик: каждый роутер уменьшает на 1', 'Время жизни сайта', 'Тип протокола', 'Длина пакета в байтах', 0, 'Когда TTL доходит до 0, пакет уничтожают. Так пакет не может вечно кружить по петле.'),
    (2, 'Какая команда показывает путь пакета через роутеры?', 'tracert (traceroute)', 'ping', 'ipconfig', 'nslookup', 0, 'tracert отправляет пакеты с TTL 1, 2, 3… и выводит каждый роутер на пути.'),
    (2, 'Какой командой узнать IP-адрес сайта по его имени?', 'nslookup', 'tracert', 'netstat', 'ipconfig', 0, 'nslookup gmcode.ru спросит DNS-сервер и покажет IP сайта. В Linux также есть dig.'),
    (2, 'Что такое порт в TCP и UDP?', 'Номер программы на устройстве', 'Разъём на роутере', 'Скорость соединения', 'Номер подсети', 0, 'IP-адрес — как адрес дома, порт — номер квартиры: какой программе отдать данные.'),
    (2, 'Компьютер получил адрес 169.254.12.7. Что это значит?', 'Он не получил адрес от DHCP', 'Это адрес сайта Google', 'Это публичный адрес', 'Это адрес роутера', 0, '169.254.x.x компьютер назначает себе сам, когда DHCP-сервер не ответил. В интернет с ним не выйти.'),
    (2, 'Чем статический IP отличается от динамического?', 'Статический задан вручную', 'Статический всегда быстрее', 'Динамический только в IPv6', 'Ничем не отличается', 0, 'Статический прописывают вручную, и он не меняется. Динамический выдаёт DHCP, и он может смениться.'),
    (2, 'На каком уровне модели OSI работает роутер?', 'Сетевом (3-й)', 'Физическом (1-й)', 'Канальном (2-й)', 'Прикладном (7-й)', 0, 'Роутер смотрит на IP-адреса — это сетевой уровень. Свитч работает на канальном (MAC).'),
    (3, 'Что такое VLAN?', 'Логическая сеть поверх общих свитчей', 'Беспроводная сеть', 'Разновидность VPN', 'Тип сетевого кабеля', 0, 'VLAN делит общую сеть коммутаторов на несколько независимых сетей, например «бухгалтерия» и «гости».'),
    (3, 'Что такое CIDR?', 'Адресация с префиксом /N', 'Протокол шифрования', 'Тип сетевого кабеля', 'Служба доменных имён', 0, 'Бесклассовая адресация: маску пишут префиксом, например 10.0.0.0/22. Размер сети — любая степень двойки, а не только /8, /16, /24.'),
    (3, 'Для чего обычно используют сеть /30?', 'Для канала между двумя роутерами', 'Для большого офиса', 'Для всего интернета', 'Для гостевого Wi-Fi', 0, 'В /30 всего 2 адреса для устройств — ровно столько нужно для связи «точка-точка».'),
    (3, 'Что означает маршрут 0.0.0.0/0?', 'Маршрут по умолчанию', 'Запрет всех пакетов', 'Маршрут только в локальную сеть', 'Адрес DNS-сервера', 0, 'Под /0 подходит любой адрес. Его используют, если более точного маршрута в таблице нет, — обычно в интернет.'),
    (3, 'Подходят несколько маршрутов. Какой выберет роутер?', 'С самым длинным префиксом', 'Первый в таблице', 'Случайный', 'С самым коротким префиксом', 0, 'Чем длиннее префикс, тем точнее маршрут: /24 точнее, чем /16, а /16 — чем 0.0.0.0/0.'),
    (3, 'Какая запись покрывает ровно 192.168.0.0/24 и 192.168.1.0/24?', '192.168.0.0/23', '192.168.0.0/25', '192.168.2.0/23', '192.168.0.0/22', 0, 'Две соседние /24 складываются в одну /23 — это агрегация маршрутов. /22 захватила бы ещё две лишние сети.'),
    (3, 'Какой диапазон зарезервирован под loopback в IPv4?', '127.0.0.0/8', '10.0.0.0/8', '169.254.0.0/16', '192.168.0.0/16', 0, 'Любой адрес 127.x.x.x — это сам компьютер. Чаще всего пишут 127.0.0.1 (localhost).'),
    (3, 'Что означает IPv6-адрес ::1?', 'Сам компьютер (loopback)', 'Адрес роутера', 'Широковещательный адрес', 'Адрес DNS Google', 0, '::1 — то же самое, что 127.0.0.1 в IPv4: обращение компьютера к самому себе.'),
    (3, 'Что в IPv6 используется вместо broadcast?', 'Multicast', 'NAT', 'DHCP', 'ARP', 0, 'В IPv6 broadcast нет. Рассылку «всем в сегменте» делает multicast, например на адрес ff02::1.'),
    (3, 'Для чего нужен протокол ICMP?', 'Служебные сообщения: ошибки и ping', 'Передача почты', 'Передача файлов', 'Шифрование трафика', 0, 'ICMP сообщает, что узел недоступен или TTL истёк. На нём же работают ping и tracert.'),
    (3, 'Что такое MTU?', 'Максимальный размер пакета на канале', 'Маска для больших сетей', 'Скорость канала', 'Время ответа сервера', 0, 'В Ethernet MTU обычно 1500 байт. Больший пакет приходится дробить или отбрасывать.'),
    (3, 'Что показывает команда netstat?', 'Сетевые соединения и порты', 'Путь пакета до узла', 'IP-адрес сайта', 'Скорость Wi-Fi', 0, 'netstat -an выводит открытые порты и текущие подключения компьютера.'),
    (3, 'Что такое DMZ в сети компании?', 'Зона для серверов, видных из интернета', 'Зона без Wi-Fi', 'Резервный канал провайдера', 'Список запрещённых сайтов', 0, 'В DMZ ставят, например, веб-сервер: он доступен снаружи, но отделён от внутренней сети.'),
    (3, 'Сколько бит в адресе IPv6?', '128', '32', '64', '256', 0, 'IPv4 — 32 бита, IPv6 — 128 бит. Адресов в IPv6 хватит с огромным запасом.')
) AS v(level, question, answer1, answer2, answer3, answer4, correct, explanation)
WHERE NOT EXISTS (SELECT 1 FROM public.network_questions);

COMMIT;

ALTER TABLE public.network_questions OWNER TO gamecode_user;
